@extends('layouts.app') @section('title','Мобильная вахта') @section('content')<style>.gate-btn{min-height:58px;font-size:1.15rem}.gate-result{font-size:1.2rem}</style><h1 class="h4">🛡 Вахта</h1><div class="row g-2"><div class="col-6"><button class="btn btn-success w-100 gate-btn dir" data-dir="in">⬇ ВХОД</button></div><div class="col-6"><button class="btn btn-outline-danger w-100 gate-btn dir" data-dir="out">⬆ ВЫХОД</button></div></div><button id="cam" class="btn btn-primary w-100 gate-btn mt-2">📷 СКАНИРОВАТЬ QR</button><video id="video" playsinline class="w-100 mt-2 rounded" style="background:#111;max-height:55vh"></video><form id="manual" class="mt-2"><input id="token" class="form-control form-control-lg" placeholder="Или сканер / токен"><button class="btn btn-secondary w-100 gate-btn mt-2">ПРОВЕРИТЬ</button></form><div id="result" class="alert d-none mt-3 gate-result"></div><div class="d-grid gap-2 mt-3"><a href="{{route('dormitory.visitors')}}" class="btn btn-outline-secondary gate-btn">🪪 Посетители</a><a href="{{route('dormitory.keys')}}" class="btn btn-outline-secondary gate-btn">🔑 Ключи</a><a href="{{route('dormitory.night')}}" class="btn btn-outline-secondary gate-btn">🌙 Ночная проверка</a></div><script>let direction='in';document.querySelectorAll('.dir').forEach(b=>b.onclick=()=>{direction=b.dataset.dir;document.querySelectorAll('.dir').forEach(x=>x.classList.remove('btn-success','btn-danger'));b.classList.add(direction==='in'?'btn-success':'btn-danger')});async function send(token){let r=await fetch('{{route('dormitory.gate.scan')}}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{csrf_token()}}'},body:JSON.stringify({token,direction})});let j=await r.json();let e=result;e.className='alert mt-3 gate-result '+(j.ok?'alert-success':'alert-danger');e.innerHTML=j.ok?'<b>'+j.student+'</b><br>'+j.building+' · комната '+j.room:(j.message||'Ошибка');}manual.onsubmit=e=>{e.preventDefault();send(token.value.trim())};cam.onclick=async()=>{if(!('BarcodeDetector'in window)){alert('Камера QR недоступна в этом браузере. Используйте сканер.');return}let s=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=s;await video.play();let d=new BarcodeDetector({formats:['qr_code']});let busy=false;setInterval(async()=>{if(busy)return;busy=true;try{let x=await d.detect(video);if(x.length)await send(x[0].rawValue)}catch(e){}busy=false},900)};</script>@endsection